// Biomedical Debate Practice Test 5. Original questions written for Valus on the 2026–27 resolution,
// "Limited healthcare resources should be allocated to patients with the greatest likelihood of
// long-term survival." Slightly harder than the sample items, covering material not used in Tests 1–4.
import {q, mix} from './q.js';
const LEVY='Levy, Breaking the Age Code (2022)', BH='Bognar & Hirose, The Ethics of Health Care Rationing', EMAN='Emanuel et al., NEJM (2020)', PERSAD='Persad, Wertheimer & Emanuel, The Lancet (2009)', OPTN='Organ Procurement and Transplantation Network';
const SCAR='Scarcity and Levels of Allocation', ETH='Ethical Theories and Principles', CRIT='Allocation Criteria and Frameworks', CASE='Real-World Allocation Cases', AGE='Aging, Longevity and Equity';

export default {
 id:'biomedical-debate-5',
 event:'Biomedical Debate',
 title:'Practice Test 5',
 subtitle:'Round One test simulation on the 2026–27 resolution',
 minutes:60,
 sources:'Levy’s Breaking the Age Code, Bognar and Hirose’s The Ethics of Health Care Rationing and published allocation frameworks',
 plan:[{area:'Resolution: Allocating Limited Healthcare Resources',weight:100,topics:[SCAR,ETH,CRIT,CASE,AGE]}],
 questions:mix([
  q(SCAR,'A health plan refuses to cover a costly treatment at all. Which form of rationing is this?','Rationing by denial',['Rationing by delay','Rationing by dilution','Rationing by deflection'],'A','Denial excludes a service entirely; delay uses waiting lists and dilution spreads it thinly.',BH),
  q(SCAR,'A clinic redirects patients it cannot serve to another agency or service. Which form of rationing is this?','Rationing by deflection',['Rationing by denial','Rationing by termination','Rationing by price'],'B','Deflection shifts demand elsewhere, which can hide the true level of unmet need.',BH),
  q(SCAR,'Calabresi and Bobbitt’s 1978 book on how societies decide who receives scarce, life-saving goods is titled:','Tragic Choices',['Setting Limits','Just Health Care','The Painful Prescription'],'C','They argued that every method of allocating such goods carries moral costs that societies try to hide.',BH),
  q(SCAR,'The observation that “a built hospital bed is a filled bed” is known as:','Roemer’s law',['Moore’s law','Murphy’s law','Parkinson’s law'],'D','Roemer’s law suggests supply can create its own demand, which complicates judging true need.',BH),
  q(SCAR,'Organs recovered after the heart has stopped, rather than after brain death, come from which type of donation?','Donation after circulatory death',['Living donation','Donation after brain death','Directed donation'],'A','Expanding this type of donation increases the organ supply but raises its own ethical questions.',OPTN),
  q(SCAR,'Two living donors who are incompatible with their own intended recipients swap kidneys with each other’s recipient. What is this called?','Paired kidney exchange',['Deceased-donor allocation','Directed donation','Domino transplantation'],'B','Paired exchanges and longer donor chains increase the number of living-donor transplants.',OPTN),
  q(SCAR,'Why are platelet shortages especially common in blood banks?','Platelets last only about 5 to 7 days after collection',['Platelets can be stored frozen for 10 years','Platelets are made in factories, not donated','Only one blood type can donate platelets'],'C','Short shelf life means supply must be refilled constantly by donors.',BH),
  q(SCAR,'In mass casualty triage, a patient tagged red is in which category?','Immediate',['Delayed','Minor','Expectant'],'D','Red means life-threatening injuries that can likely be survived with prompt care.',BH),
  q(SCAR,'The START mass casualty triage system sorts patients mainly by checking which three things?','Breathing, circulation and ability to follow commands',['Age, insurance status and full past medical history','Blood type, height, weight and current medicines list','Pain level, body temperature and any known allergies'],'A','START stands for Simple Triage and Rapid Treatment and can be done in under a minute.',BH),
  q(ETH,'A doctor gives high-dose pain medicine intending relief, while foreseeing it may shorten life. Which principle is often used to justify this?','Doctrine of double effect',['Rule of rescue','Difference principle','Harm principle'],'B','The principle separates intended effects from foreseen but unintended ones.',BH),
  q(ETH,'Which form of utilitarianism judges each decision by its own results rather than by following general rules?','Act utilitarianism',['Rule utilitarianism','Virtue utilitarianism','Contract utilitarianism'],'C','A rule utilitarian might follow a fixed triage rule even when breaking it seems better in one case.',BH),
  q(ETH,'Ronald Dworkin asked what health insurance a prudent person would buy if wealth were fairly distributed and medical facts were known. What is this called?','The prudent insurance ideal',['The veil of ignorance','The fair innings argument','The rule of rescue'],'D','Dworkin argued that most prudent people would not buy coverage for very costly, low-benefit care at life’s end.',BH),
  q(ETH,'People who are fully insured may use more health care than they would if they paid directly. What is this economic concept?','Moral hazard',['Adverse selection','Opportunity cost','Diminishing returns'],'A','Some argue moral hazard justifies cost-sharing, while critics say it discourages needed care.',BH),
  q(ETH,'John Stuart Mill’s principle that society may limit freedom only to prevent harm to others is called the:','Harm principle',['Difference principle','Precautionary principle','Principle of utility'],'B','The harm principle is often raised in debates over penalizing patients for risky behaviors.',BH),
  q(ETH,'Which thought experiment asks whether it is right to divert a runaway trolley to kill one person instead of five?','The trolley problem',['The lifeboat dilemma','The prisoner’s dilemma','The ship of Theseus'],'C','It is often used to test intuitions about saving the greater number.',BH),
  q(ETH,'Which ethical approach, developed by thinkers such as Carol Gilligan, focuses on relationships and responsibilities to vulnerable people?','Ethics of care',['Act utilitarianism','Libertarianism','Social contract theory'],'D','Care ethicists warn that impersonal scoring systems can overlook patients’ relationships and needs.',BH),
  q(ETH,'Focusing on whether the process for deciding allocation is fair, open and consistent concerns which kind of justice?','Procedural justice',['Retributive justice','Restorative justice','Commutative justice'],'A','When people disagree about outcomes, a fair process can make decisions more legitimate.',BH),
  q(ETH,'Reasoning that compares a new dilemma with clear past cases, rather than starting from a single theory, is called:','Casuistry',['Deontology','Egoism','Relativism'],'B','Casuistry is common in clinical ethics consultations, where similar past cases guide new decisions.',BH),
  q(CRIT,'A treatment lowers the risk of death from 10% to 5%. What is the number needed to treat to prevent one death?','20',['5','10','50'],'C','The absolute risk reduction is 10% − 5% = 5%, so NNT = 1 ÷ 0.05 = 20 patients.',BH),
  q(CRIT,'A program costs $30,000 and adds 5 life-years. What is its cost per life-year gained?','$6,000',['$150,000','$25,000','$3,000'],'D','Divide cost by benefit: $30,000 ÷ 5 life-years = $6,000 per life-year gained.',BH),
  q(CRIT,'A drug cuts the risk of death from 2% to 1%. Which statement is accurate?','Absolute risk falls 1 point; relative risk falls 50%',['Absolute risk falls 50 points; relative risk falls 1%','Absolute risk falls 2 points; relative risk falls 100%','Both absolute and relative risk fall by exactly 50%'],'A','Relative risk reductions can sound much larger than the absolute benefit.',BH),
  q(CRIT,'Some 2020 ventilator protocols barred patients with certain conditions, such as advanced dementia, from receiving ventilators at all. What are these rules called?','Categorical exclusion criteria',['Lottery-based tie-breaking rules','Scheduled reassessment rules','Reciprocity priority criteria'],'B','Disability advocates argued that blanket exclusions violated civil rights laws.',EMAN),
  q(CRIT,'A patient receives a ventilator for a set period, after which progress is reviewed. What is this approach called?','A time-limited trial',['A lottery draw','A first-come allocation','A permanent assignment'],'C','Time-limited trials let clinicians give patients a chance while allowing later reallocation.',EMAN),
  q(CRIT,'A treatment that has almost no chance of achieving its medical goal is often described as:','Medically futile',['Cost-effective','Experimental','Elective'],'D','Futility judgments are controversial because they can mix medical facts with value judgments.',BH),
  q(CRIT,'In transplant allocation, giving organs to the sickest patients can conflict with giving them to patients with the best expected results. Which two goals are in tension?','Urgency and utility',['Equality and liberty','Autonomy and privacy','Efficiency and speed'],'A','Most allocation systems balance urgency and utility rather than choosing one alone.',OPTN),
  q(CRIT,'Surveys that ask how much people would pay to gain a health benefit measure:','Willingness to pay',['Discount rate','Disability weight','Time trade-off'],'B','Willingness-to-pay studies are used to set cost-effectiveness thresholds, though they favor the wealthy.',BH),
  q(CRIT,'How does cost-benefit analysis differ from cost-utility analysis?','Cost-benefit analysis puts health outcomes in dollars',['Cost-benefit analysis ignores costs entirely','Cost-utility analysis uses only lives saved','They always give identical results'],'C','Cost-utility analysis measures outcomes in QALYs instead of money.',BH),
  q(CRIT,'An intervention is both cheaper and more effective than the current standard. How is it described?','Dominant',['Dominated','Cost-neutral','Cost-ineffective'],'D','A dominant option should be chosen on cost-effectiveness grounds, since no trade-off is needed.',BH),
  q(CRIT,'An analysis estimates the total amount a health budget would spend if a new drug were adopted for all eligible patients. What is this called?','A budget impact analysis',['A cost per QALY analysis','A sensitivity analysis','A survival analysis'],'A','A drug can be cost-effective per patient yet unaffordable when used by many patients.',BH),
  q(CRIT,'Norway’s priority-setting criteria weigh health benefit and resource use together with which third factor?','Severity of the condition',['Patient’s income','Social status','Date of application'],'B','Norway gives more weight to benefits for patients with more severe conditions.',BH),
  q(CRIT,'The systematic evaluation of a drug or device’s effectiveness, cost and social effects to guide coverage decisions is called:','Health technology assessment',['Clinical trial registration','Utilization review','Peer review'],'C','Agencies such as NICE in England perform health technology assessment to guide coverage.',BH),
  q(CRIT,'On the scale used to calculate QALYs, what do the values 0 and 1 represent?','0 is death and 1 is full health',['0 is full health and 1 is death','0 is birth and 1 is old age','0 is no cost and 1 is full cost'],'D','Some methods allow negative values for states considered worse than death.',BH),
  q(CASE,'Many U.S. liver transplant centers traditionally required six months of sobriety before listing patients with alcohol-related liver disease. Why was this rule challenged?','Some patients die before reaching six months',['It was required by federal law','It favored patients with hepatitis','It applied only to children'],'A','Studies of early transplant for selected patients found good outcomes, leading many centers to relax the rule.',OPTN),
  q(CASE,'The Inflation Reduction Act of 2022 capped insulin costs at how much per month for Medicare patients?','$35',['$5','$100','$250'],'B','High insulin prices had led some patients to ration their own doses, sometimes with fatal results.',BH),
  q(CASE,'In 2017, a UK court case drew global attention over whether an infant with a rare mitochondrial disease could travel for experimental treatment. Who was the patient?','Charlie Gard',['Sarah Murnaghan','Terri Schiavo','Karen Ann Quinlan'],'C','The case raised questions about futility, parental rights and best interests.',BH),
  q(CASE,'During COVID-19 surges, which scarce therapy that circulates and oxygenates blood outside the body required strict allocation?','ECMO',['Dialysis','Blood pressure cuffs','Oral antibiotics'],'D','ECMO needs specialized staff and long treatment times, so centers set strict eligibility rules.',EMAN),
  q(CASE,'In 2022, Medicare limited coverage of the Alzheimer’s drug Aduhelm to patients in approved studies. What is this policy called?','Coverage with evidence development',['Step therapy requirement','Prior authorization review','Compassionate use program'],'A','It allowed access while gathering more evidence about uncertain benefits.',BH),
  q(CASE,'Early in the COVID-19 pandemic, a surge in demand for hydroxychloroquine caused shortages for which patients?','Patients with lupus and rheumatoid arthritis',['Patients with seasonal allergies','Patients with broken bones','Patients with tooth decay'],'B','The case shows how unproven uses can take supply away from patients who rely on a drug.',BH),
  q(CASE,'From 2022 to 2024, heavy demand for weight-loss use caused shortages of which drug, used by people with type 2 diabetes?','Semaglutide (Ozempic)',['Albuterol (ProAir)','Amoxicillin (Amoxil)','Acetaminophen (Tylenol)'],'C','Patients with diabetes reported difficulty filling prescriptions during the shortage.',BH),
  q(CASE,'In 2022, a U.S. shortage of which product led to emergency imports and federal action?','Infant formula',['Insulin pens','Flu vaccines','Blood pressure cuffs'],'D','A plant closure at one major manufacturer revealed how concentrated the supply was.',BH),
  q(CASE,'In many states, undocumented immigrants with kidney failure could receive dialysis only when near death. What is this practice called?','Emergency-only dialysis',['Home hemodialysis','Peritoneal dialysis','Scheduled outpatient dialysis'],'A','Studies found this approach led to more suffering, higher costs and higher death rates.',BH),
  q(CASE,'Which country faced worldwide criticism for using organs from executed prisoners in transplants?','China',['Spain','Norway','Canada'],'B','China announced in 2015 that it would rely only on voluntary civilian donors.',BH),
  q(AGE,'Levy’s research found that younger adults who held negative age stereotypes were more likely to experience which outcome decades later?','A heart attack or stroke',['Higher income','Better eyesight','Fewer hospital visits'],'C','The finding suggests age beliefs absorbed early in life may affect later cardiovascular health.',LEVY),
  q(AGE,'In explaining why positive age beliefs were linked to longer life, Levy found that which factor partly accounted for the effect?','A stronger will to live',['Higher wealth','More years of school','A larger family'],'D','Positive self-perceptions of aging were linked to a greater will to live.',LEVY),
  q(AGE,'In the U.S., a person who reaches age 65 can expect to live about how many more years on average?','About 19 years',['About 5 years','About 10 years','About 35 years'],'A','Life expectancy at 65 is far higher than many assume from life expectancy at birth.',LEVY),
  q(AGE,'Speaking to older adults in a slow, simplified, sing-song way, as if to a child, is called:','Elderspeak',['Plain language','Teach-back','Active listening'],'B','Levy cites elderspeak as a common form of ageism that can lower older adults’ performance.',LEVY),
  q(AGE,'How does geriatrics differ from gerontology?','Geriatrics is medical care; gerontology studies aging broadly',['Geriatrics studies aging in animals; gerontology studies it in people','Gerontology is the study of child and adolescent development only','They are two names for one medical specialty with the same training'],'C','Gerontology covers the biological, psychological and social sides of aging.',LEVY),
  q(AGE,'The Age-Friendly Health Systems model focuses on “4Ms.” What are they?','What Matters, Medication, Mentation and Mobility',['Money, Meals, Medicine and Marriage','Memory, Muscles, Metabolism and Mood','Monitoring, Measuring, Managing and Moving'],'D','The model aims to give older adults care that fits their goals and avoids harm.',LEVY),
  q(AGE,'Linda Fried’s frailty phenotype includes weight loss, exhaustion, weakness, slow walking and which other sign?','Low physical activity',['High blood pressure','Poor eyesight','Hair loss'],'A','Frailty, not age alone, predicts poor outcomes and is used in some triage tools.',LEVY),
  q(AGE,'The limit on how many times normal human cells can divide before stopping is known as the:','Hayflick limit',['Gompertz curve','Peter principle','Dunbar number'],'B','The limit is linked to the shortening of telomeres at the ends of chromosomes.',LEVY)
 ],9544)
};
